/**
 * The passive tree: ~600 nodes laid out in six attribute sectors around a central start.
 *
 *   Might (STR) · Finesse (DEX) · Arcana (INT) and the hybrids between them.
 *
 * Each sector has a spine of attribute nodes, wheel clusters (a notable ringed by minors), skill
 * clusters (a node that unlocks an active skill plus three enhancements of that skill), jewel
 * sockets, keystones (rule changers) and, at the rim, a repeatable mastery for endless points.
 * Two rings join the sectors so builds can travel. The layout is generated by code from the
 * tables below (deterministic), so adding a notable or a skill is a one-line change.
 */
import { mod, type Mod, type StatId, type Tag } from './stats';

export type NodeKind = 'start' | 'minor' | 'notable' | 'keystone' | 'skill' | 'skillmod' | 'socket' | 'mastery';
export type Sector = 'str' | 'str_dex' | 'dex' | 'dex_int' | 'int' | 'int_str' | 'center';

export interface TreeNode {
  id: string;
  kind: NodeKind;
  name: string;
  x: number;
  y: number;
  sector: Sector;
  mods: Mod[];
  skill?: string;
  desc?: string;
  links: string[];
  /** Mastery nodes can be allocated any number of times. */
  repeatable?: boolean;
}

export interface Tree {
  nodes: TreeNode[];
  byId: Map<string, TreeNode>;
  start: string;
}

const SECTOR_ANGLE: Record<Exclude<Sector, 'center'>, number> = {
  str: 90, str_dex: 150, dex: 210, dex_int: 270, int: 330, int_str: 30,
};
export const SECTOR_COLOR: Record<Sector, string> = {
  str: '#e0584a', str_dex: '#e0a24a', dex: '#5ad06a', dex_int: '#4ac0c8', int: '#5a8aff', int_str: '#b06ae0', center: '#e8e4da',
};
export const SECTOR_NAME: Record<Sector, string> = {
  str: 'Might', str_dex: 'Bloodsport', dex: 'Finesse', dex_int: 'Shadow', int: 'Arcana', int_str: 'Zealotry', center: 'Origin',
};

// ---------------------------------------------------------------- content tables

type M = Mod;
const inc = (stat: StatId, v: number, tags?: Tag[]) => mod(stat, 'inc', v, tags);
const flat = (stat: StatId, v: number, tags?: Tag[]) => mod(stat, 'flat', v, tags);
const more = (stat: StatId, v: number, tags?: Tag[]) => mod(stat, 'more', v, tags);
const flag = (stat: StatId) => mod(stat, 'flag', 1);

