// ---------------------------------------------------------------- layout

function buildTree(): Tree {
  const nodes: TreeNode[] = [];
  const byId = new Map<string, TreeNode>();
  const add = (n: Omit<TreeNode, 'links'>): TreeNode => {
    const node = { ...n, links: [] as string[], x: Math.round(n.x), y: Math.round(n.y) };
    nodes.push(node);
    byId.set(node.id, node);
    return node;
  };
  const link = (a: TreeNode, b: TreeNode) => {
    if (a.id === b.id || a.links.includes(b.id)) return;
    a.links.push(b.id);
    b.links.push(a.id);
  };
  const at = (r: number, deg: number) => ({ x: r * Math.cos((deg * Math.PI) / 180), y: r * Math.sin((deg * Math.PI) / 180) });
  const minorName = (m: M[]) => (m.length > 1 ? 'Versatility' : ({
    str: 'Strength', dex: 'Dexterity', int: 'Intelligence', life: 'Vitality', mana: 'Wisdom', armor: 'Toughness', evasion: 'Agility',
    attackSpeed: 'Swiftness', castSpeed: 'Incantation', critChance: 'Precision', critMulti: 'Lethality', damage: 'Force', lifeRegen: 'Recovery',
    lifeLeech: 'Leech', lifeOnHit: 'Vampirism', moveSpeed: 'Fleetness', stagger: 'Impact', area: 'Reach', cooldownRecovery: 'Celerity',
    manaRegen: 'Clarity', freezeChance: 'Rime', igniteChance: 'Kindling', shockChance: 'Static', poisonChance: 'Venom', bleedChance: 'Rend',
    resFire: 'Fire Ward', resLightning: 'Storm Ward', critMulti_: '',
  } as Record<string, string>)[m[0].stat] ?? 'Passive');

  const start = add({ id: 'start', kind: 'start', name: 'Origin', x: 0, y: 0, sector: 'center', mods: [] });
  const sectors = Object.keys(SECTOR_ANGLE) as Array<Exclude<Sector, 'center'>>;
  const innerRing: TreeNode[] = [];
  const outerRing: TreeNode[] = [];
  let socketN = 0;

  for (const sec of sectors) {
    const ang = SECTOR_ANGLE[sec];
    const minors = MINORS[sec];
    let mi = 0;
    const nextMinor = () => minors[mi++ % minors.length];
    const minorNode = (id: string, x: number, y: number) => {
      const m = nextMinor();
      return add({ id, kind: 'minor', name: minorName(m), x, y, sector: sec, mods: m });
    };
    // Spine: 13 nodes from r=110 to r=1010.
    const spine: TreeNode[] = [];
    for (let i = 0; i < 13; i++) {
      const p = at(110 + i * 75, ang + Math.sin(i * 0.9) * 2.5);
      spine.push(minorNode(`${sec}_sp${i}`, p.x, p.y));
      if (i) link(spine[i - 1], spine[i]);
    }
    link(start, spine[0]);
    innerRing.push(spine[2]);
    outerRing.push(spine[8]);

    // Wheel clusters off the spine, alternating sides.
    const notables = NOTABLES[sec];
    notables.forEach((nd, k) => {
      const i = 1 + Math.floor((k * 11) / notables.length);
      const side = k % 2 ? 1 : -1;
      const r = 150 + i * 75;
      const off = side * (15 + (k % 3) * 3) * (300 / Math.max(300, r));
      const c = at(r + 40, ang + off);
      const notable = add({ id: `${sec}_n${k}`, kind: 'notable', name: nd.name, x: c.x, y: c.y, sector: sec, mods: nd.mods.filter((m) => m.value !== 0 || m.kind === 'flag') });
      const wheel: TreeNode[] = [];
      const count = 4 + (k % 3);
      for (let j = 0; j < count; j++) {
        const a = (j / count) * Math.PI * 2 + (ang * Math.PI) / 180;
        wheel.push(minorNode(`${sec}_n${k}_w${j}`, c.x + Math.cos(a) * 46, c.y + Math.sin(a) * 46));
      }
      wheel.forEach((w, j) => link(w, wheel[(j + 1) % count]));
      link(notable, wheel[0]);
      link(notable, wheel[Math.floor(count / 2)]);
      // Attach the wheel to the closest spine node.
      let best = spine[0], bd = Infinity;
      for (const w of wheel) for (const sp of spine) {
        const d = Math.hypot(w.x - sp.x, w.y - sp.y);
        if (d < bd) {
          bd = d;
          best = sp;
          void w;
        }
      }
      let closest = wheel[0], cd = Infinity;
      for (const w of wheel) {
        const d = Math.hypot(w.x - best.x, w.y - best.y);
        if (d < cd) {
          cd = d;
          closest = w;
        }
      }
      link(closest, best);
    });

    // Skill clusters: a short branch ending in the skill node, enhancements fanning out past it.
    const clusters = [...SKILL_CLUSTERS[sec], ...CORE_SKILL_MODS.filter((c) => c.sector === sec).map((c) => ({ ...c, core: true }))] as Array<SkillCluster & { core?: boolean }>;
    clusters.forEach((cl, k) => {
      const i = 1 + ((k * 4) % 9);
      const side = k % 2 ? -1 : 1;
      const r = 110 + i * 75;
      const base = spine[i];
      const branchA = at(r + 10, ang + side * 23 * (400 / Math.max(400, r)));
      const b1 = minorNode(`${sec}_s${k}_b`, branchA.x, branchA.y);
      link(base, b1);
      const sp = at(r + 30, ang + side * 31 * (400 / Math.max(400, r)));
      const skillNode = cl.core
        ? b1
        : add({ id: `${sec}_s${k}`, kind: 'skill', name: cl.skill, x: sp.x, y: sp.y, sector: sec, mods: [], skill: cl.skill });
      if (!cl.core) link(b1, skillNode);
      cl.mods.forEach((m, j) => {
        const p = at(r + 30 + (j - 1) * 42, ang + side * (39 + Math.abs(j - 1) * -3) * (400 / Math.max(400, r)));
        const mn = add({ id: `${sec}_s${k}_m${j}`, kind: 'skillmod', name: m.name, x: p.x, y: p.y, sector: sec, mods: m.mods, desc: `${cl.skill} enhancement` });
        link(skillNode, mn);
      });
    });

    // Keystones: one at the spine tip, two on side branches near the rim.
    const ks = KEYSTONES[sec];
    const tip = spine[spine.length - 1];
    ks.forEach((k, j) => {
      const p = j === 0 ? at(1100, ang) : at(990, ang + (j === 1 ? -14 : 14));
      const node = add({ id: `ks_${k.id}`, kind: 'keystone', name: k.name, desc: k.desc, x: p.x, y: p.y, sector: sec, mods: k.mods.filter((m) => m.value !== 0 || m.kind === 'flag') });
      if (j === 0) link(tip, node);
      else {
        const via = at(930, ang + (j === 1 ? -9 : 9));
        const v = minorNode(`${sec}_k${j}`, via.x, via.y);
        link(spine[10], v);
        link(v, node);
      }
    });
    // Mastery past the main keystone (repeatable).
    const ms = MASTERY[sec];
    const mp = at(1185, ang);
    const mastery = add({ id: `mastery_${sec}`, kind: 'mastery', name: ms.name, x: mp.x, y: mp.y, sector: sec, mods: ms.mods, repeatable: true, desc: 'Can be allocated any number of times.' });
    link(byId.get(`ks_${ks[0].id}`)!, mastery);
    // Jewel sockets.
    for (const i of [5, 9]) {
      const p = at(110 + i * 75, ang + (i === 5 ? 9 : -10));
      const sock = add({ id: `socket${socketN++}`, kind: 'socket', name: 'Jewel Socket', x: p.x, y: p.y, sector: sec, mods: [] });
      link(spine[i], sock);
    }
  }

  // Rings between neighbouring sectors (minor nodes along arcs).
  const ring = (anchors: TreeNode[], radius: number, perGap: number, tag: string) => {
    for (let i = 0; i < anchors.length; i++) {
      const a = anchors[i], b = anchors[(i + 1) % anchors.length];
      const sa = SECTOR_ANGLE[a.sector as Exclude<Sector, 'center'>], sb = SECTOR_ANGLE[b.sector as Exclude<Sector, 'center'>];
      let span = sb - sa;
      if (span <= 0) span += 360;
      let prev = a;
      for (let k = 1; k <= perGap; k++) {
        const deg = sa + (span * k) / (perGap + 1);
        const p = at(radius, deg);
        const sec = (k <= perGap / 2 ? a.sector : b.sector) as Exclude<Sector, 'center'>;
        const m = MINORS[sec][(k + i) % MINORS[sec].length];
        const n = add({ id: `${tag}${i}_${k}`, kind: 'minor', name: minorName(m), x: p.x, y: p.y, sector: sec, mods: m });
        link(prev, n);
        prev = n;
      }
      link(prev, b);
    }
  };
  const order = (list: TreeNode[]) => [...list].sort((p, q) => SECTOR_ANGLE[p.sector as Exclude<Sector, 'center'>] - SECTOR_ANGLE[q.sector as Exclude<Sector, 'center'>]);
  ring(order(innerRing), 260, 3, 'ri');
  ring(order(outerRing), 710, 7, 'ro');
  return { nodes, byId, start: start.id };
}

export const TREE: Tree = buildTree();

/** Shortest unallocated path from the allocated set to `target` (node ids to allocate, in order). */
export function pathTo(allocated: ReadonlySet<string>, target: string, tree: Tree = TREE): string[] {
  if (allocated.has(target) && !tree.byId.get(target)?.repeatable) return [];
  const sources = allocated.size ? [...allocated, tree.start] : [tree.start];
  const prev = new Map<string, string | null>();
  const q: string[] = [];
  for (const s0 of sources) {
    prev.set(s0, null);
    q.push(s0);
  }
  for (let i = 0; i < q.length; i++) {
    const cur = q[i];
    if (cur === target) break;
    for (const n of tree.byId.get(cur)?.links ?? []) {
      if (prev.has(n)) continue;
      prev.set(n, cur);
      q.push(n);
    }
  }
  if (!prev.has(target)) return [];
  const out: string[] = [];
  for (let c: string | null = target; c && !allocated.has(c) && c !== tree.start; c = prev.get(c) ?? null) out.unshift(c);
  if (allocated.has(target) && tree.byId.get(target)?.repeatable) out.push(target);
  return out;
}

/** Nodes that can be refunded without disconnecting others from the start. */
export function canRefund(allocated: readonly string[], id: string, tree: Tree = TREE): boolean {
  const set = new Set(allocated);
  if (!set.has(id)) return false;
  const count = allocated.filter((x) => x === id).length;
  if (count > 1) return true;
  set.delete(id);
  const seen = new Set<string>([tree.start]);
  const q = [tree.start];
  for (let i = 0; i < q.length; i++)
    for (const n of tree.byId.get(q[i])?.links ?? [])
      if (set.has(n) && !seen.has(n)) {
        seen.add(n);
        q.push(n);
      }
  for (const a of set) if (!seen.has(a)) return false;
  return true;
}
